    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '301: A 25-year-old with an opioid overdose has: pH 7.22, pCO2 65, pO2 55. A-a Gradient is likely:', '["Elevated", "Normal", "Decreased", "Zero"]', 1, 'In pure hypoventilation (opioids), the lungs are healthy, so the A-a gradient remains normal.'),
    (v_topic_id, '302: A 65-year-old with pneumonia has: pH 7.48, pCO2 30, pO2 55. A-a Gradient is:', '["Normal", "Elevated", "Decreased", "Unchanged"]', 1, 'Hypoxia caused by intrinsic lung disease (pneumonia) always results in an elevated A-a gradient.'),
    (v_topic_id, '303: Which mechanism of hypoxia is the only one with a NORMAL A-a gradient?', '["Shunt", "V/Q mismatch", "Hypoventilation or High Altitude", "Diffusion defect"]', 2, 'In these cases, the problem is not getting O2 into the blood, but rather a lack of O2 in the alveoli itself.'),
    (v_topic_id, '304: A patient with "Anemia" (Hb = 7 g/dL) but normal lungs will have:', '["Normal pO2 and SaO2, but low Oxygen Content", "Low pO2", "Low SaO2", "High pH"]', 0, 'Dissolved O2 and saturation of available Hb are normal; there just isn''t enough Hb to carry a normal total volume of O2.'),
    (v_topic_id, '305: "PaO2 / FiO2" ratio (P/F ratio) < 300 defines:', '["Normal lungs", "Acute Lung Injury (ALI) or ARDS", "Heart failure", "Pneumonia"]', 1, 'A P/F ratio < 200 is part of the Berlin definition for moderate ARDS.'),
    (v_topic_id, '306: A patient with pH 7.30, pCO2 50, HCO3 24. Interpretation?', '["Acute Respiratory Acidosis", "Chronic Respiratory Acidosis", "Metabolic Acidosis", "Mixed disorder"]', 0, 'The 1-for-10 rule applies: pCO2 is 10 above normal, HCO3 has risen by ~1. No time for renal compensation.'),
    (v_topic_id, '307: A patient with pH 7.36, pCO2 50, HCO3 28. Interpretation?', '["Acute Respiratory Acidosis", "Chronic Respiratory Acidosis", "Normal", "Metabolic Alkalosis"]', 1, 'The 4-for-10 rule applies: pCO2 10 above normal, HCO3 risen by 4. This matches chronic compensation.'),
    (v_topic_id, '308: Which of the following causes a HAGMA with a "Fruity" breath odor?', '["Methanol", "DKA", "Uremia", "Lactic Acidosis"]', 1, 'Acetone, a byproduct of ketosis, is exhaled and has a characteristic fruity smell.'),
    (v_topic_id, '309: A "Positive" Delta-Gap (Delta AG - Delta HCO3 > 6) suggests:', '["Concomitant Metabolic Alkalosis", "Concomitant NAGMA", "Pure HAGMA", "Respiratory Acidosis"]', 0, 'The bicarbonate has not fallen as much as expected for the rise in AG.'),
    (v_topic_id, '310: A "Negative" Delta-Gap (Delta AG - Delta HCO3 < -6) suggests:', '["Concomitant Metabolic Alkalosis", "Concomitant Normal Anion Gap Metabolic Acidosis (NAGMA)", "Pure HAGMA", "Normal state"]', 1, 'The bicarbonate has fallen MORE than expected, indicating a second acidosis.'),
    (v_topic_id, '311: "Propylene Glycol" toxicity is most likely in which patient?', '["A diabetic", "A patient on a high-dose Lorazepam drip in the ICU", "An alcoholic", "A hiker at high altitude"]', 1, 'Propylene glycol is the solvent used in IV lorazepam and other drugs.'),
    (v_topic_id, '312: "Isopropyl Alcohol" differs from Methanol because Isopropyl Alcohol does NOT cause:', '["Elevated Osmolar Gap", "Metabolic Acidosis (AG remains normal)", "Ketosis", "Inebriation"]', 1, 'It is metabolized to acetone, which is not an acid, whereas methanol is metabolized to formic acid.'),
    (v_topic_id, '313: "Hyperchloremia" following 5 liters of Normal Saline is a classic cause of:', '["HAGMA", "NAGMA", "Metabolic Alkalosis", "Respiratory Acidosis"]', 1, 'Excess chloride leads to renal bicarbonate excretion to maintain electrical neutrality.'),
    (v_topic_id, '314: "Proximal (Type 2) RTA" is a defect in the _____ of bicarbonate.', '["Secretion", "Reabsorption", "Production", "Filtering"]', 1, 'The proximal tubule fails to reabsorb the bulk of filtered HCO3.'),
    (v_topic_id, '315: "Distal (Type 1) RTA" is a defect in the _____ of hydrogen ions.', '["Secretion", "Reabsorption", "Production", "Filtering"]', 0, 'The alpha-intercalated cells cannot secrete H+ against a gradient.'),
    (v_topic_id, '316: Which RTA is most commonly associated with "Autoimmune" diseases like Sj\u00f6gren''s?', '["Type 1", "Type 2", "Type 4", "None"]', 0, 'Type 1 Distal RTA.'),
    (v_topic_id, '317: A patient with "Renal Colic" taking large doses of "NSAIDs" is at risk for which RTA?', '["Type 4 (due to Hyporeninemic Hypoaldosteronism)", "Type 1", "Type 2", "None"]', 0, 'NSAIDs inhibit prostaglandins, which are necessary for renin release.'),
    (v_topic_id, '318: "Hyperkalemia" is the diagnostic clue for:', '["Type 1 RTA", "Type 2 RTA", "Type 4 RTA", "Diarrhea"]', 2, 'It is the only RTA that presents with high serum potassium.'),
    (v_topic_id, '319: "Metabolic Alkalosis" + "Hypokalemia" + "Low Blood Pressure" + "High Urine Chloride" =', '["Vomiting", "Bartter or Gitelman Syndrome", "Conn Syndrome", "Diuretic use (currently)"]', 1, 'These syndromes mimic chronic diuretic use (salt-wasting).'),
    (v_topic_id, '320: "Metabolic Alkalosis" + "Hypokalemia" + "High Blood Pressure" + "High Urine Chloride" =', '["Vomiting", "Mineralocorticoid Excess (e.g., Conn or Cushing)", "Gitelman", "Diarrhea"]', 1, 'The body is volume expanded due to mineralocorticoid activity.'),
    (v_topic_id, '321: "Metabolic Alkalosis" + "Hypokalemia" + "Low Urine Chloride" =', '["Vomiting (remote)", "Diuretic use (remote)", "Nasogastric suction", "All of the above"]', 3, 'These are all "Chloride-responsive" states.'),
    (v_topic_id, '322: The "Spinal Cord" injury at which level will cause Respiratory Acidosis (Apnea)?', '["C3, C4, C5 (Phrenic nerve origin)", "T10", "L1", "S2"]', 0, '"C3, 4, 5 keep the diaphragm alive."'),
    (v_topic_id, '323: "Acute Pulmonary Edema" can cause which acid-base disorder?', '["Respiratory Alkalosis (initially, due to tachypnea)", "Respiratory Acidosis (if severe/tiring)", "Metabolic Acidosis (if low output/lactic)", "Any of the above"]', 3, 'It is a complex clinical state that can present with multiple disturbances.'),
    (v_topic_id, '324: "Respiratory Alkalosis" in a patient with a "Liver" problem is a sign of:', '["Hepatitis", "Hepatic Encephalopathy / Cirrhosis (due to ammonia stimulation of breathing)", "Gallstones", "Liver cancer"]', 1, 'Cirrhotic patients often have a baseline chronic respiratory alkalosis.'),
    (v_topic_id, '325: A "Low pCO2" in a patient with "Metabolic Acidosis" is:', '["A primary disorder", "The compensatory response", "A sign of heart failure", "Error"]', 1, 'The body hyperventilates to "wash out" CO2 and raise the pH.'),
    (v_topic_id, '326: A patient with pH 7.40, pCO2 40, HCO3 24, and Anion Gap 30 has:', '["Normal ABG", "Mixed HAGMA and Metabolic Alkalosis", "Pure HAGMA", "Pure Metabolic Alkalosis"]', 1, 'The very high AG (30) proves a HAGMA exists, but since the pH and HCO3 are normal, an equal and opposite metabolic alkalosis must also be present.'),
    (v_topic_id, '327: "Base Excess" of +10 mEq/L suggests:', '["Metabolic Acidosis", "Metabolic Alkalosis", "Respiratory Acidosis", "Normal"]', 1, 'Positive values indicate an excess of base.'),
    (v_topic_id, '328: "Carboxyhemoglobin" does NOT change the:', '["pO2 (which remains normal as it represents dissolved O2)", "SaO2", "O2 content", "Skin color"]', 0, 'This is why CO poisoning is so deceptive; the ABG pO2 looks perfect but the patient is dying of hypoxia.'),
    (v_topic_id, '329: "Methemoglobinemia" can be triggered by which common medication?', '["Aspirin", "Local anesthetics (e.g., Benzocaine), Nitrites, or Dapsone", "Penicillin", "Insulin"]', 1, 'These act as oxidizing agents.'),
    (v_topic_id, '330: "Methemoglobinemia" gives the blood a characteristic _____ color.', '["Bright red", "Chocolate-brown", "Blue", "Clear"]', 1, 'It does not change color when exposed to oxygen.'),
    (v_topic_id, '331: Which imaging modality is useful for evaluating "Acute Dyspnea" but NOT acid-base status directly?', '["Chest X-ray", "Ultrasound (Blue Protocol)", "CT scan", "All of the above"]', 3, 'Imaging helps find the *cause* of the respiratory disorder.'),
    (v_topic_id, '332: "K+ / H+ Exchange" in the distal tubule is regulated by:', '["Insulin", "Aldosterone", "Thyroxine", "Vitamin D"]', 1, 'Aldosterone promotes Na+ reabsorption and K+/H+ secretion.'),
    (v_topic_id, '333: A patient with pH 7.20, pCO2 20, HCO3 8. What is the expected pCO2 by Winter''s?', '["10", "20", "30", "40"]', 1, '(1.5 * 8) + 8 = 12 + 8 = 20. The compensation is perfect.'),
    (v_topic_id, '334: A patient has pH 7.30, pCO2 60, HCO3 30. Interpretation?', '["Acute Respiratory Acidosis", "Chronic Respiratory Acidosis", "Acute on Chronic Respiratory Acidosis", "Metabolic Acidosis"]', 2, 'For pCO2 60, HCO3 should be 26 (acute) or 32 (chronic). 30 falls in between, suggesting an acute worsening of a chronic state.'),
    (v_topic_id, '335: "High Gap Acidosis" is usually due to:', '["Addition of acid", "Loss of base", "Gain of base", "Loss of salt"]', 0, 'New anions are added to the blood.'),
    (v_topic_id, '336: "Normal Gap Acidosis" is usually due to:', '["Addition of acid", "Loss of bicarbonate (base) and replacement by Chloride", "Heart failure", "Panic"]', 1, 'This maintains electrical neutrality without adding new anions.'),
    (v_topic_id, '337: "Urine Anion Gap" is only reliable if:', '["The urine is bloody", "Urine pH is relatively constant and there are no other unmeasured anions (like ketones) in the urine", "Sodium is high", "Potassium is low"]', 1, 'Presence of ketones or other organic acids in the urine makes the UAG uninterpretable.'),
    (v_topic_id, '338: A "Delta-Delta" of 0.5 suggests:', '["Pure HAGMA", "HAGMA and NAGMA (mixed acidosis)", "HAGMA and Metabolic Alkalosis", "Respiratory Acidosis"]', 1, 'The HCO3 has fallen twice as much as the AG has risen.'),
    (v_topic_id, '339: "Methanol" metabolism: Methanol -> Formaldehyde -> Formic Acid. Which enzyme performs the first step?', '["Alcohol Dehydrogenase", "Aldehyde Dehydrogenase", "Carbonic Anhydrase", "Protease"]', 0, 'This is the target for Fomepizole therapy.'),
    (v_topic_id, '340: "Ethylene Glycol" metabolism: Ethylene Glycol -> Glycolaldehyde -> Glycolic Acid -> Glyoxylic Acid -> Oxalic Acid. Which metabolite causes the most severe HAGMA?', '["Glycolic Acid", "Oxalic Acid", "Glycolaldehyde", "Formaldehyde"]', 0, 'Glycolic acid is the primary driver of the AG acidosis.'),
    (v_topic_id, '341: "Ketones" are: Acetoacetate, Beta-hydroxybutyrate, and:', '["Acetone", "Lactate", "Pyruvate", "Glucose"]', 0, 'Only the first two are acids.'),
    (v_topic_id, '342: "DKA" is diagnosed by the triad of:', '["High sugar, high AG, and positive ketones", "High sugar, low pH, and cough", "Normal sugar, high AG, and fever", "Low sugar and high AG"]', 0, 'The glucose is usually > 250 mg/dL, but "Euglycemic DKA" can occur with SGLT2 inhibitors.'),
    (v_topic_id, '343: "Euglycemic DKA" is a risk in patients taking:', '["SGLT2 inhibitors (e.g., Empagliflozin)", "Metformin", "Insulin", "Sulfonylureas"]', 0, 'The kidneys continue to spill glucose, masking the severity of the ketosis.'),
    (v_topic_id, '344: A patient has pH 7.55, pCO2 48, HCO3 40. This is:', '["Respiratory Alkalosis", "Metabolic Alkalosis with appropriate compensation", "Mixed Metabolic and Respiratory Alkalosis", "Respiratory Acidosis"]', 1, 'The pH is alkaline and the primary driver is high HCO3; the pCO2 has risen to compensate.'),
    (v_topic_id, '345: "Hypothermia" management: "pH-stat" involves:', '["Correcting values to 37\u00b0C", "Correcting values to the patient''s actual temperature (adding CO2 if needed)", "Ignoring pH", "Giving base"]', 1, 'This is sometimes used during cardiac surgery.'),
    (v_topic_id, '346: "Hypothermia" management: "Alpha-stat" involves:', '["Measuring values at 37\u00b0C regardless of patient temperature", "Keeping pH at 7.0", "Adding oxygen", "High pCO2"]', 0, 'This is the standard approach in many centers.'),
    (v_topic_id, '347: "Arterial" blood is typically _____ than venous blood.', '["Darker", "Brighter red (due to oxygenation)", "Clear", "Thicker"]', 1, 'Observation of the color during the draw can help confirm arterial placement.'),
    (v_topic_id, '348: A "Pulsatile" flow into the syringe confirms:', '["Venous placement", "Arterial placement", "Capillary placement", "Nerve hit"]', 1, 'This is a key procedural indicator.'),
    (v_topic_id, '349: The "Normal" ratio of HCO3 to dissolved CO2 (0.03 * pCO2) at pH 7.40 is:', '["1:1", "10:1", "20:1", "100:1"]', 2, '24 / (0.03 * 40) = 24 / 1.2 = 20.'),
    (v_topic_id, '350: ABG interpretation is best mastered by:', '["Memorizing rules", "Practicing with clinical scenarios and correlating with the patient''s story", "Trusting the computer", "Only looking at the pH"]', 1, 'The clinical context is inseparable from the numbers on the paper.');
